package uz.mirix.tracelens.internal;
import org.aopalliance.intercept.MethodInterceptor;import org.springframework.aop.framework.ProxyFactory;import org.springframework.beans.BeansException;import org.springframework.beans.factory.config.BeanPostProcessor;import org.springframework.data.redis.connection.*;import uz.mirix.tracelens.TraceLensProperties;import java.lang.reflect.Modifier;
public final class TraceLensRedisConnectionFactoryBeanPostProcessor implements BeanPostProcessor {private final TraceLensProperties p;public TraceLensRedisConnectionFactoryBeanPostProcessor(TraceLensProperties p){this.p=p;}public Object postProcessAfterInitialization(Object bean,String beanName)throws BeansException{if(!p.isEnabled()||!p.getRedis().isEnabled()||!(bean instanceof RedisConnectionFactory)||Modifier.isFinal(bean.getClass().getModifiers()))return bean;ProxyFactory f=new ProxyFactory(bean);f.setProxyTargetClass(true);f.addAdvice((MethodInterceptor)i->{Object result=i.proceed();if(result instanceof RedisConnection c&&("getConnection".equals(i.getMethod().getName())||"getClusterConnection".equals(i.getMethod().getName())))return RedisProxyFactory.wrap(c);return result;});return f.getProxy(bean.getClass().getClassLoader());}}
